class AuditLogEntry {
    private String logId;
    private String userAction;
    private String operatorId;
    private long epochSeconds;

    public AuditLogEntry(String logId, String action, String operator, long timestamp) {
        this.logId = logId;
        this.userAction = action;
        this.operatorId = operator;
        this.epochSeconds = timestamp;
    }

    public String getLogId() { return logId; }
    public String getUserAction() { return userAction; }
    public String getOperatorId() { return operatorId; }
    public long getEpochSeconds() { return epochSeconds; }

    public void printAuditSummary() {
        System.out.println("LOG [" + logId + "] Operator: " + operatorId + " performed '" + userAction + "' at " + epochSeconds);
    }
}

public class Main {
    public static void main(String[] args) {
        AuditLogEntry entry = new AuditLogEntry("TX-9901", "DATABASE_EXPORT", "admin_sam", 1740000000L);
        entry.printAuditSummary();

        // Outside code CANNOT change entry.userAction or call setUserAction()!
        // The audit record is completely immutable and trustworthy.
        System.out.println("Verified Action: " + entry.getUserAction());
    }
}

