class BankCustomer {
    // Permanently immutable field (Read-Only)
    private String panNumber;
    private String accountId;

    // Controlled mutable field
    private String homeAddress;

    public BankCustomer(String pan, String accId, String address) {
        this.panNumber = pan;
        this.accountId = accId;
        this.homeAddress = address;
    }

    // Read-only getters: NO SETTERS for PAN or Account ID
    public String getPanNumber() { return panNumber; }
    public String getAccountId() { return accountId; }

    // Mutable getter & setter for address only
    public String getHomeAddress() { return homeAddress; }
    public void setHomeAddress(String newAddress) {
        if (newAddress != null && !newAddress.trim().isEmpty()) {
            this.homeAddress = newAddress.trim();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        BankCustomer cust = new BankCustomer("ABCDE1234F", "ACC-00192", "12 MG Road");
        System.out.println("Customer ID: " + cust.getAccountId() + " (Permanent)");

        // Moving homes: address can change, identity cannot!
        cust.setHomeAddress("45 Park Avenue");
        System.out.println("New Address: " + cust.getHomeAddress());
    }
}

