class ReadOnlyColor {
    private int red;
    private int green;
    private int blue;

    public ReadOnlyColor(int r, int g, int b) {
        this.red = clamp(r);
        this.green = clamp(g);
        this.blue = clamp(b);
    }

    private int clamp(int val) {
        if (val < 0) return 0;
        if (val > 255) return 255;
        return val;
    }

    public int getRed() { return red; }
    public int getGreen() { return green; }
    public int getBlue() { return blue; }

    public ReadOnlyColor withRed(int newRed) {
        return new ReadOnlyColor(newRed, this.green, this.blue);
    }

    public String toRgbString() {
        return red + ", " + green + ", " + blue;
    }
}

public class Main {
    public static void main(String[] args) {
        ReadOnlyColor c1 = new ReadOnlyColor(100, 150, 200);
        ReadOnlyColor c2 = c1.withRed(255);
        System.out.println("Original: " + c1.toRgbString() + " | Revised: " + c2.toRgbString());
    }
}
